    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --panel: #ffffff;
        --panel-border: #d8e1f0;
        --text: #172033;
        --muted: #55627a;
        --accent: #2563eb;
        --accent-strong: #1d4ed8;
        --accent-soft: #dbeafe;
        --shadow: 0 20px 45px rgba(15, 23, 42, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 24px;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, #eef4ff 0%, #f4f7fb 40%, #edf2f9 100%);
        color: var(--text);
      }

      main {
        width: min(100%, 560px);
      }

      .card {
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: 24px;
        padding: 32px;
        box-shadow: var(--shadow);
      }

      .eyebrow {
        margin: 0 0 12px;
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
        color: var(--accent-strong);
      }

      h1 {
        margin: 0 0 10px;
        font-size: clamp(1.75rem, 3vw, 2.25rem);
        line-height: 1.15;
      }

      .intro {
        margin: 0 0 28px;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 24px;
      }

      .form-field {
        display: grid;
        gap: 14px;
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
        min-width: 0;
      }

      legend {
        margin-bottom: 10px;
        font-size: 1.05rem;
        font-weight: 700;
      }

      .options {
        display: grid;
        gap: 12px;
      }

      .option {
        position: relative;
      }

      .option label {
        display: flex;
        align-items: center;
        gap: 14px;
        padding: 16px 18px;
        border: 1px solid var(--panel-border);
        border-radius: 16px;
        background: #fff;
        color: var(--text);
        cursor: pointer;
        transition:
          border-color 0.2s ease,
          box-shadow 0.2s ease,
          background-color 0.2s ease,
          transform 0.2s ease;
      }

      .option label:hover {
        border-color: #b8c7e4;
        transform: translateY(-1px);
      }

      .option input {
        margin: 0;
        inline-size: 1.15rem;
        block-size: 1.15rem;
        accent-color: var(--accent);
      }

      .option input:focus-visible + span {
        outline: 3px solid transparent;
      }

      .option label:has(input:focus-visible) {
        outline: 3px solid var(--accent);
        outline-offset: 2px;
      }

      .option label:has(input:checked) {
        border-color: var(--accent);
        background: var(--accent-soft);
        box-shadow: 0 0 0 1px var(--accent);
      }

      .option-text {
        font-weight: 600;
      }

      button {
        justify-self: start;
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
        cursor: pointer;
        box-shadow: 0 14px 28px rgba(37, 99, 235, 0.28);
        transition:
          transform 0.2s ease,
          box-shadow 0.2s ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 16px 30px rgba(37, 99, 235, 0.32);
      }

      button:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: 3px;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--muted);
        font-weight: 600;
      }

      @media (max-width: 480px) {
        .card {
          padding: 24px;
          border-radius: 20px;
        }

        button {
          width: 100%;
          justify-self: stretch;
        }
      }

      @media (forced-colors: active) {
        body {
          background: Canvas;
        }

        .card,
        .option label,
        button {
          border: 1px solid ButtonText;
          box-shadow: none;
        }

        .card,
        .option label {
          background: Canvas;
          color: CanvasText;
        }

        .option label:has(input:checked) {
          background: Highlight;
          color: HighlightText;
        }

        button {
          background: ButtonFace;
          color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <main>
      <section class="card" aria-labelledby="page-title">
        <p class="eyebrow">Preferences</p>
        <h1 id="page-title">Choose your notification preference</h1>
        <p class="intro">
          Select one option so we know how you prefer to receive notifications.
        </p>

        <form id="notification-form">
          <div class="form-field">
            <fieldset>
              <legend>How do you prefer to receive notifications?</legend>
              <div class="options">
                <div class="option">
                  <label for="notification-email">
                    <input
                      id="notification-email"
                      type="radio"
                      name="notificationPreference"
                      value="Email"
                      required
                    />
                    <span class="option-text">Email</span>
                  </label>
                </div>
                <div class="option">
                  <label for="notification-sms">
                    <input
                      id="notification-sms"
                      type="radio"
                      name="notificationPreference"
                      value="SMS"
                    />
                    <span class="option-text">SMS</span>
                  </label>
                </div>
                <div class="option">
                  <label for="notification-push">
                    <input
                      id="notification-push"
                      type="radio"
                      name="notificationPreference"
                      value="Push Notifications"
                    />
                    <span class="option-text">Push Notifications</span>
                  </label>
                </div>
              </div>
            </fieldset>
          </div>

          <button type="submit">Submit</button>
          <p class="status" id="form-status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("notification-form");
      const status = document.getElementById("form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const selectedOption = form.querySelector(
          'input[name="notificationPreference"]:checked'
        );

        status.textContent = selectedOption
          ? `Preference saved: ${selectedOption.value}.`
          : "Please choose one notification method before submitting.";
      });
    </script>
  </body>
</html>
